// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(uint256 salt) public {
        // Deploy an eligible caller contract (EOA fuzzed addresses would revert in supportsToken).
        // The salt lets the fuzzer search the caller-address space while staying admissible.
        Caller caller = new Caller{salt: bytes32(salt)}(c);
        // Pre-state: balance is zero, so airDrop must succeed and credit 20 to the caller.
        require(c.tokenBalance(address(caller)) == 0);
        caller.go();
        // General rule: after a successful airDrop by a zero-balance authorized caller,
        // tokenBalance(caller) must equal 20.
        assertTrue(c.tokenBalance(address(caller)) == 20);
    }
}

// Adversarial counterparty: airDrop's supportsToken modifier calls into msg.sender,
// so the caller must be a contract implementing supportsToken.
contract Caller {
    ModifierEntrancy immutable c;
    constructor(ModifierEntrancy c_) { c = c_; }
    function go() external { c.airDrop(); }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
